import java.util.Scanner;
public class JInput1 {
	public static void main(String[] args) {
		//Paso 1: Leer el primer entero que ingresa el usuario
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese un entero:");
		int num = scan.nextInt();
		//Paso 2: Imprimir el entero que el usuario ha ingresado, luego recibir los siguientes enteros mientras el usuario ingrese un entero no negativo; de lo contrario detenerse
		while ( num >= 0 ) {
			System.out.println("El entero ingresado es " + num);
			System.out.println("Ingrese un entero:");
			num = scan.nextInt(); 
		}
		scan.close();
		System.out.println("Fin de la entrada.");
	}
}

